insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Immune system', 'The immune system is a network of biological systems that protects an organism from diseases. It detects and responds to a wide variety of pathogens, such as viruses, bacteria, and parasites, as well as cancer cells and foreign objects, such as wood splinters—distinguishing them from the organism''s own healthy tissue. Many species have two major subsystems of the immune system. The innate immune system provides a preconfigured response to broad groups of situations and stimuli. The adaptive immune system provides a tailored response to each stimulus by learning to recognize molecules it has previously encountered. Both use specialised molecules and cells to perform their functions. Nearly all organisms have some kind of immune system. Bacteria have a rudimentary immune system in the form of enzymes that protect against viral infections. Other basic immune mechanisms evolved in ancient plants and animals (eukaryotes) and remain in their modern descendants. These mechanisms include phagocytosis, antimicrobial peptides called defensins, RNA interference, and the complement system. Jawed vertebrates, including humans, have a more sophisticated defense mechanism. For example, adaptive immunity provides the ability to adapt to recognize pathogens more efficiently (somatic hypermutation). This process creates an immunological memory, resulting in an enhanced response against subsequent encounters with that same pathogen. This mechanism of adaptive immunity is the fundamental basis of vaccination.', 'Wikipedia: Immune system', 'https://en.wikipedia.org/w/index.php?title=Immune_system&oldid=1378735926', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The immune system is a network of biological systems that protects an organism from diseases. It detects and responds to a wide variety of pathogens, such as viruses, bacteria, and parasites, as well as cancer cells and foreign objects, such as wood splinters—distinguishing them from the organism''s own healthy tissue. Many species have two major subsystems of the immune system. The innate immune system provides a preconfigured response to broad groups of situations and stimuli. The adaptive immune system provides a tailored response to each stimulus by learning to recognize molecules it has previously encountered. Both use specialised molecules and cells to perform their functions. Nearly all organisms have some kind of immune system. Bacteria have a rudimentary immune system in the form of enzymes that protect against viral infections. Other basic immune mechanisms evolved in ancient plants and animals (eukaryotes) and remain in their modern descendants. These mechanisms include phagocytosis, antimicrobial peptides called defensins, RNA interference, and the complement system. Jawed vertebrates, including humans, have a more sophisticated defense mechanism. For example, adaptive immunity provides the ability to adapt to recognize pathogens more efficiently (somatic hypermutation). This process creates an immunological memory, resulting in an enhanced response against subsequent encounters with that same pathogen. This mechanism of adaptive immunity is the fundamental basis of vaccination.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Immune system', 'Dysfunction of the immune system can cause autoimmune diseases, inflammatory diseases and cancer. Immunodeficiency occurs when the immune system is less active than normal, resulting in recurring and life-threatening infections. In humans, immunodeficiency can be the result of a genetic disease such as severe combined immunodeficiency, acquired conditions such as HIV/AIDS, or the use of immunosuppressive medication. Autoimmunity results from a hyperactive immune system attacking normal tissues as if they were foreign organisms. Common autoimmune diseases include Hashimoto''s thyroiditis, rheumatoid arthritis, diabetes mellitus type 1, and systemic lupus erythematosus. Immunology covers the study of all aspects of the immune system.', 'Wikipedia: Immune system', 'https://en.wikipedia.org/w/index.php?title=Immune_system&oldid=1378735926', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Dysfunction of the immune system can cause autoimmune diseases, inflammatory diseases and cancer. Immunodeficiency occurs when the immune system is less active than normal, resulting in recurring and life-threatening infections. In humans, immunodeficiency can be the result of a genetic disease such as severe combined immunodeficiency, acquired conditions such as HIV/AIDS, or the use of immunosuppressive medication. Autoimmunity results from a hyperactive immune system attacking normal tissues as if they were foreign organisms. Common autoimmune diseases include Hashimoto''s thyroiditis, rheumatoid arthritis, diabetes mellitus type 1, and systemic lupus erythematosus. Immunology covers the study of all aspects of the immune system.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Immune system: Layered defense', 'The immune system protects its host from infection with layered defenses of increasing specificity. Physical barriers prevent pathogens such as bacteria and viruses from entering the organism. If a pathogen breaches these barriers, the innate immune system provides an immediate, but non-specific response. Innate immune systems are found in all animals. If pathogens successfully evade the innate response, vertebrates possess a second layer of protection, the adaptive immune system, which is activated by the innate response. Here, the immune system adapts its response during an infection to improve its recognition of the pathogen. This improved response is then retained after the pathogen has been eliminated, in the form of an immunological memory, and allows the adaptive immune system to mount faster and stronger attacks each time this pathogen is encountered. Both innate and adaptive immunity depend on the ability of the immune system to distinguish between self and non-self molecules. In immunology, self molecules are components of an organism''s body that can be distinguished from foreign substances by the immune system. Conversely, non-self molecules are those recognized as foreign molecules. One class of non-self molecules is called antigens (originally named for being antibody generators) and are defined as substances that bind to specific immune receptors and elicit an immune response.', 'Wikipedia: Immune system', 'https://en.wikipedia.org/w/index.php?title=Immune_system&oldid=1378735926', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The immune system protects its host from infection with layered defenses of increasing specificity. Physical barriers prevent pathogens such as bacteria and viruses from entering the organism. If a pathogen breaches these barriers, the innate immune system provides an immediate, but non-specific response. Innate immune systems are found in all animals. If pathogens successfully evade the innate response, vertebrates possess a second layer of protection, the adaptive immune system, which is activated by the innate response. Here, the immune system adapts its response during an infection to improve its recognition of the pathogen. This improved response is then retained after the pathogen has been eliminated, in the form of an immunological memory, and allows the adaptive immune system to mount faster and stronger attacks each time this pathogen is encountered. Both innate and adaptive immunity depend on the ability of the immune system to distinguish between self and non-self molecules. In immunology, self molecules are components of an organism''s body that can be distinguished from foreign substances by the immune system. Conversely, non-self molecules are those recognized as foreign molecules. One class of non-self molecules is called antigens (originally named for being antibody generators) and are defined as substances that bind to specific immune receptors and elicit an immune response.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Immune system: Surface barriers', 'Several barriers protect organisms from infection, including mechanical, chemical, and biological barriers. The waxy cuticle of most leaves, the exoskeleton of insects, the shells and membranes of externally deposited eggs, and skin are examples of mechanical barriers that are the first line of defense against infection. Organisms cannot be completely sealed from their environments, so systems act to protect body openings such as the lungs, intestines, and the genitourinary tract. In the lungs, coughing and sneezing mechanically eject pathogens and other irritants from the respiratory tract. The flushing action of tears and urine also mechanically expels pathogens, while mucus secreted by the respiratory and gastrointestinal tract serves to trap and entangle microorganisms. Chemical barriers also protect against infection. The skin and respiratory tract secrete antimicrobial peptides such as the β-defensins. Enzymes such as lysozyme and phospholipase A2 in saliva, tears, and breast milk are also antibacterials. Vaginal secretions serve as a chemical barrier following menarche, when they become slightly acidic, while semen contains defensins and zinc to kill pathogens. In the stomach, gastric acid serves as a chemical defense against ingested pathogens.', 'Wikipedia: Immune system', 'https://en.wikipedia.org/w/index.php?title=Immune_system&oldid=1378735926', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Several barriers protect organisms from infection, including mechanical, chemical, and biological barriers. The waxy cuticle of most leaves, the exoskeleton of insects, the shells and membranes of externally deposited eggs, and skin are examples of mechanical barriers that are the first line of defense against infection. Organisms cannot be completely sealed from their environments, so systems act to protect body openings such as the lungs, intestines, and the genitourinary tract. In the lungs, coughing and sneezing mechanically eject pathogens and other irritants from the respiratory tract. The flushing action of tears and urine also mechanically expels pathogens, while mucus secreted by the respiratory and gastrointestinal tract serves to trap and entangle microorganisms. Chemical barriers also protect against infection. The skin and respiratory tract secrete antimicrobial peptides such as the β-defensins. Enzymes such as lysozyme and phospholipase A2 in saliva, tears, and breast milk are also antibacterials. Vaginal secretions serve as a chemical barrier following menarche, when they become slightly acidic, while semen contains defensins and zinc to kill pathogens. In the stomach, gastric acid serves as a chemical defense against ingested pathogens.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Immune system: Surface barriers', 'Within the genitourinary and gastrointestinal tracts, commensal flora serve as biological barriers by competing with pathogenic bacteria for food and space and, in some cases, changing the conditions in their environment, such as pH or available iron. As a result, the probability that pathogens will reach sufficient numbers to cause illness is reduced.', 'Wikipedia: Immune system', 'https://en.wikipedia.org/w/index.php?title=Immune_system&oldid=1378735926', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Within the genitourinary and gastrointestinal tracts, commensal flora serve as biological barriers by competing with pathogenic bacteria for food and space and, in some cases, changing the conditions in their environment, such as pH or available iron. As a result, the probability that pathogens will reach sufficient numbers to cause illness is reduced.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Immune system: Innate immune system', 'Microorganisms or toxins that successfully enter an organism encounter the cells and mechanisms of the innate immune system. The innate response is usually triggered when microbes are identified by pattern recognition receptors, which recognize components that are conserved among broad groups of microorganisms, or when damaged, injured or stressed cells send out alarm signals, many of which are recognized by the same receptors as those that recognize pathogens. Innate immune defenses are non-specific, meaning these systems respond to pathogens in a generic way. This system does not confer long-lasting immunity against a pathogen. The innate immune system is the dominant system of host defense in most organisms, and the only one in plants.', 'Wikipedia: Immune system', 'https://en.wikipedia.org/w/index.php?title=Immune_system&oldid=1378735926', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Microorganisms or toxins that successfully enter an organism encounter the cells and mechanisms of the innate immune system. The innate response is usually triggered when microbes are identified by pattern recognition receptors, which recognize components that are conserved among broad groups of microorganisms, or when damaged, injured or stressed cells send out alarm signals, many of which are recognized by the same receptors as those that recognize pathogens. Innate immune defenses are non-specific, meaning these systems respond to pathogens in a generic way. This system does not confer long-lasting immunity against a pathogen. The innate immune system is the dominant system of host defense in most organisms, and the only one in plants.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Immune system: Immune sensing', 'Cells in the innate immune system use pattern recognition receptors to recognize molecular structures that are produced by pathogens. They are proteins expressed, mainly, by cells of the innate immune system, such as dendritic cells, macrophages, monocytes, neutrophils, and epithelial cells, to identify two classes of molecules: pathogen-associated molecular patterns (PAMPs), which are associated with microbial pathogens, and damage-associated molecular patterns (DAMPs), which are associated with components of hosts'' cells that are released during cell damage or cell death. Cells in the innate immune system have pattern recognition receptors that detect internal infection or cell damage. Three major classes of these "cytosolic" receptors are NOD–like receptors, RIG (retinoic acid-inducible gene)-like receptors, and cytosolic DNA sensors. Recognition of extracellular or endosomal PAMPs is mediated by transmembrane proteins known as toll-like receptors (TLRs). TLRs share a typical structural motif, the leucine rich repeats (LRRs), which give them a curved shape. Toll-like receptors were first discovered in Drosophila and trigger the synthesis and secretion of cytokines and activation of other host defense programs that are necessary for both innate or adaptive immune responses. Ten toll-like receptors have been described in humans.', 'Wikipedia: Immune system', 'https://en.wikipedia.org/w/index.php?title=Immune_system&oldid=1378735926', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Cells in the innate immune system use pattern recognition receptors to recognize molecular structures that are produced by pathogens. They are proteins expressed, mainly, by cells of the innate immune system, such as dendritic cells, macrophages, monocytes, neutrophils, and epithelial cells, to identify two classes of molecules: pathogen-associated molecular patterns (PAMPs), which are associated with microbial pathogens, and damage-associated molecular patterns (DAMPs), which are associated with components of hosts'' cells that are released during cell damage or cell death. Cells in the innate immune system have pattern recognition receptors that detect internal infection or cell damage. Three major classes of these "cytosolic" receptors are NOD–like receptors, RIG (retinoic acid-inducible gene)-like receptors, and cytosolic DNA sensors. Recognition of extracellular or endosomal PAMPs is mediated by transmembrane proteins known as toll-like receptors (TLRs). TLRs share a typical structural motif, the leucine rich repeats (LRRs), which give them a curved shape. Toll-like receptors were first discovered in Drosophila and trigger the synthesis and secretion of cytokines and activation of other host defense programs that are necessary for both innate or adaptive immune responses. Ten toll-like receptors have been described in humans.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Immune system: Innate immune cells', 'Some leukocytes (white blood cells) act like independent, single-celled organisms and are the second arm of the innate immune system. The innate leukocytes include the "professional" phagocytes (macrophages, neutrophils, and dendritic cells). These cells identify and eliminate pathogens, either by attacking larger pathogens through contact or by engulfing and then killing microorganisms. The other cells involved in the innate response include innate lymphoid cells, mast cells, eosinophils, basophils, and natural killer cells. Phagocytosis is an important feature of cellular innate immunity performed by cells called phagocytes that engulf pathogens or particles. Phagocytes generally patrol the body searching for pathogens, but can be called to specific locations by cytokines. Once a pathogen has been engulfed by a phagocyte, it becomes trapped in an intracellular vesicle called a phagosome, which subsequently fuses with another vesicle called a lysosome to form a phagolysosome. The pathogen is killed by the activity of digestive enzymes or following a respiratory burst that releases free radicals into the phagolysosome. Phagocytosis evolved as a means of acquiring nutrients, but this role was extended in phagocytes to include engulfment of pathogens as a defense mechanism. Phagocytosis probably represents the oldest form of host defense, as phagocytes have been identified in both vertebrate and invertebrate animals.', 'Wikipedia: Immune system', 'https://en.wikipedia.org/w/index.php?title=Immune_system&oldid=1378735926', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Some leukocytes (white blood cells) act like independent, single-celled organisms and are the second arm of the innate immune system. The innate leukocytes include the "professional" phagocytes (macrophages, neutrophils, and dendritic cells). These cells identify and eliminate pathogens, either by attacking larger pathogens through contact or by engulfing and then killing microorganisms. The other cells involved in the innate response include innate lymphoid cells, mast cells, eosinophils, basophils, and natural killer cells. Phagocytosis is an important feature of cellular innate immunity performed by cells called phagocytes that engulf pathogens or particles. Phagocytes generally patrol the body searching for pathogens, but can be called to specific locations by cytokines. Once a pathogen has been engulfed by a phagocyte, it becomes trapped in an intracellular vesicle called a phagosome, which subsequently fuses with another vesicle called a lysosome to form a phagolysosome. The pathogen is killed by the activity of digestive enzymes or following a respiratory burst that releases free radicals into the phagolysosome. Phagocytosis evolved as a means of acquiring nutrients, but this role was extended in phagocytes to include engulfment of pathogens as a defense mechanism. Phagocytosis probably represents the oldest form of host defense, as phagocytes have been identified in both vertebrate and invertebrate animals.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Innate immune system', 'The innate immune system or nonspecific immune system is one of the two main immunity strategies in vertebrates (the other being the adaptive immune system). The innate immune system is an alternate defense strategy and is the dominant immune system response found in plants, fungi, prokaryotes, and invertebrates (see § Beyond vertebrates). recruit immune cells to infection sites by producing chemical factors, including chemical mediators called cytokines activate the complement cascade to identify bacteria, activate cells, and promote clearance of antibody complexes or dead cells identify and remove foreign substances present in organs, tissues, blood and lymph, by specialized white blood cells act as a physical and chemical barrier to infectious agents; via physical measures such as skin and mucus, and chemical measures such as clotting factors and host defence peptides. initiate and regulate inflammatory responses by releasing inflammatory mediators (such as cytokines and chemokines), thereby promoting immune cell recruitment, increasing vascular permeability, and enhancing local immune defense at sites of infection.', 'Wikipedia: Innate immune system', 'https://en.wikipedia.org/w/index.php?title=Innate_immune_system&oldid=1364464376', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The innate immune system or nonspecific immune system is one of the two main immunity strategies in vertebrates (the other being the adaptive immune system). The innate immune system is an alternate defense strategy and is the dominant immune system response found in plants, fungi, prokaryotes, and invertebrates (see § Beyond vertebrates). recruit immune cells to infection sites by producing chemical factors, including chemical mediators called cytokines activate the complement cascade to identify bacteria, activate cells, and promote clearance of antibody complexes or dead cells identify and remove foreign substances present in organs, tissues, blood and lymph, by specialized white blood cells act as a physical and chemical barrier to infectious agents; via physical measures such as skin and mucus, and chemical measures such as clotting factors and host defence peptides. initiate and regulate inflammatory responses by releasing inflammatory mediators (such as cytokines and chemokines), thereby promoting immune cell recruitment, increasing vascular permeability, and enhancing local immune defense at sites of infection.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Innate immune system: Anatomical barriers', 'Anatomical barriers include physical, chemical and biological barriers. The epithelial surfaces form a physical barrier that is impermeable to most infectious agents, acting as the first line of defense against invading organisms. Desquamation (shedding) of skin epithelium also helps remove bacteria and other infectious agents that have adhered to the epithelial surface. Lack of blood vessels, the inability of the epidermis to retain moisture, and the presence of sebaceous glands in the dermis, produces an environment unsuitable for the survival of microbes. In the gastrointestinal and respiratory tract, movement due to peristalsis or cilia, respectively, helps remove infectious agents. Also, mucus traps infectious agents. Gut flora can prevent the colonization of pathogenic bacteria by secreting toxic substances or by competing with pathogenic bacteria for nutrients or cell surface attachment sites. The flushing action of tears and saliva helps prevent infection of the eyes and mouth.', 'Wikipedia: Innate immune system', 'https://en.wikipedia.org/w/index.php?title=Innate_immune_system&oldid=1364464376', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Anatomical barriers include physical, chemical and biological barriers. The epithelial surfaces form a physical barrier that is impermeable to most infectious agents, acting as the first line of defense against invading organisms. Desquamation (shedding) of skin epithelium also helps remove bacteria and other infectious agents that have adhered to the epithelial surface. Lack of blood vessels, the inability of the epidermis to retain moisture, and the presence of sebaceous glands in the dermis, produces an environment unsuitable for the survival of microbes. In the gastrointestinal and respiratory tract, movement due to peristalsis or cilia, respectively, helps remove infectious agents. Also, mucus traps infectious agents. Gut flora can prevent the colonization of pathogenic bacteria by secreting toxic substances or by competing with pathogenic bacteria for nutrients or cell surface attachment sites. The flushing action of tears and saliva helps prevent infection of the eyes and mouth.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Innate immune system: Epithelial barrier theory', 'The epithelial barrier hypothesis (also known as the epithelial barrier theory) is a medical concept suggesting that dysfunction of epithelial barriers, induced by environmental toxic substances such as air pollutants, detergents, food additives, microplastics, and nanoparticles, contributes to the development of chronic diseases. Barrier impairment occurs in the skin, respiratory tract, and intestines, and is often accompanied by microbial dysbiosis, bacterial translocation, tissue and systemic inflammation, and immune dysregulation. These processes have been proposed as contributing factors to allergic, autoimmune, metabolic, and neuropsychiatric disorders. The hypothesis was initially framed in the early 2020s by immunologist Cezmi Akdis and has since been discussed in independent peer-reviewed reviews in the fields of immunology, allergy, dermatology, and nutrition. Akdis introduced the concept to explain the rising prevalence of chronic inflammatory diseases in industrialized societies. It builds on earlier frameworks such as the hygiene hypothesis, and incorporates findings from microbiome research. Barrier damage: Environmental exposures including ozone, particulate matter, detergents, and synthetic particles may impair epithelial junctions, increasing permeability and allowing antigens to penetrate underlying tissues. Microbial dysbiosis: Barrier impairment can alter microbiota composition in the skin, gut, and airways, reducing microbial diversity and promoting overgrowth of opportunistic species. Immune activation: Cytokines such as interleukin-25, interleukin-33, and thymic stromal lymphopoietin are implicated in initiating type 2 inflammatory responses following barrier disruption.', 'Wikipedia: Innate immune system', 'https://en.wikipedia.org/w/index.php?title=Innate_immune_system&oldid=1364464376', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The epithelial barrier hypothesis (also known as the epithelial barrier theory) is a medical concept suggesting that dysfunction of epithelial barriers, induced by environmental toxic substances such as air pollutants, detergents, food additives, microplastics, and nanoparticles, contributes to the development of chronic diseases. Barrier impairment occurs in the skin, respiratory tract, and intestines, and is often accompanied by microbial dysbiosis, bacterial translocation, tissue and systemic inflammation, and immune dysregulation. These processes have been proposed as contributing factors to allergic, autoimmune, metabolic, and neuropsychiatric disorders. The hypothesis was initially framed in the early 2020s by immunologist Cezmi Akdis and has since been discussed in independent peer-reviewed reviews in the fields of immunology, allergy, dermatology, and nutrition. Akdis introduced the concept to explain the rising prevalence of chronic inflammatory diseases in industrialized societies. It builds on earlier frameworks such as the hygiene hypothesis, and incorporates findings from microbiome research. Barrier damage: Environmental exposures including ozone, particulate matter, detergents, and synthetic particles may impair epithelial junctions, increasing permeability and allowing antigens to penetrate underlying tissues. Microbial dysbiosis: Barrier impairment can alter microbiota composition in the skin, gut, and airways, reducing microbial diversity and promoting overgrowth of opportunistic species. Immune activation: Cytokines such as interleukin-25, interleukin-33, and thymic stromal lymphopoietin are implicated in initiating type 2 inflammatory responses following barrier disruption.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Innate immune system: Epithelial barrier theory', 'Autoimmune and metabolic disorders: type 1 diabetes, multiple sclerosis, metabolic dysfunction-associated steatotic liver disease. Neuropsychiatric conditions: preliminary research suggests possible links to neuroinflammatory disorders, such as Alzheimer''s disease. Critics of the theory argue that many associations remain correlative and emphasize the need for longitudinal human studies and standardized methods to assess epithelial barrier integrity.', 'Wikipedia: Innate immune system', 'https://en.wikipedia.org/w/index.php?title=Innate_immune_system&oldid=1364464376', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Autoimmune and metabolic disorders: type 1 diabetes, multiple sclerosis, metabolic dysfunction-associated steatotic liver disease. Neuropsychiatric conditions: preliminary research suggests possible links to neuroinflammatory disorders, such as Alzheimer''s disease. Critics of the theory argue that many associations remain correlative and emphasize the need for longitudinal human studies and standardized methods to assess epithelial barrier integrity.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Innate immune system: Inflammation', 'Inflammation is one of the first responses of the immune system to infection or irritation. Inflammation is stimulated by chemical factors released by injured cells. It establishes a physical barrier against the spread of infection and promotes healing of any damaged tissue following pathogen clearance. The process of acute inflammation is initiated by cells already present in all tissues, mainly resident macrophages, dendritic cells, histiocytes, Kupffer cells, and mast cells. These cells present receptors contained on the surface or within the cell, named pattern recognition receptors (PRRs), which recognize molecules that are broadly shared by pathogens but distinguishable from host molecules, collectively referred to as pathogen-associated molecular patterns (PAMPs). At the onset of an infection, burn, or other injuries, these cells undergo activation (one of their PRRs recognizes a PAMP) and release inflammatory mediators, like cytokines and chemokines, which are responsible for the clinical signs of inflammation. PRR activation and its cellular consequences have been well-characterized as methods of inflammatory cell death, which include pyroptosis, necroptosis, and PANoptosis. These cell death pathways help clear infected or aberrant cells and release cellular contents and inflammatory mediators.', 'Wikipedia: Innate immune system', 'https://en.wikipedia.org/w/index.php?title=Innate_immune_system&oldid=1364464376', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Inflammation is one of the first responses of the immune system to infection or irritation. Inflammation is stimulated by chemical factors released by injured cells. It establishes a physical barrier against the spread of infection and promotes healing of any damaged tissue following pathogen clearance. The process of acute inflammation is initiated by cells already present in all tissues, mainly resident macrophages, dendritic cells, histiocytes, Kupffer cells, and mast cells. These cells present receptors contained on the surface or within the cell, named pattern recognition receptors (PRRs), which recognize molecules that are broadly shared by pathogens but distinguishable from host molecules, collectively referred to as pathogen-associated molecular patterns (PAMPs). At the onset of an infection, burn, or other injuries, these cells undergo activation (one of their PRRs recognizes a PAMP) and release inflammatory mediators, like cytokines and chemokines, which are responsible for the clinical signs of inflammation. PRR activation and its cellular consequences have been well-characterized as methods of inflammatory cell death, which include pyroptosis, necroptosis, and PANoptosis. These cell death pathways help clear infected or aberrant cells and release cellular contents and inflammatory mediators.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Innate immune system: Inflammation', 'Chemical factors produced during inflammation (histamine, bradykinin, serotonin, leukotrienes, and prostaglandins) sensitize pain receptors, cause local vasodilation of the blood vessels, and attract phagocytes, especially neutrophils. Neutrophils then trigger other parts of the immune system by releasing factors that summon additional leukocytes and lymphocytes. Cytokines produced by macrophages and other cells of the innate immune system mediate the inflammatory response. These cytokines include TNF, HMGB1, and IL-1. heat, either increased local temperature, such as a warm feeling around a localized infection, or a systemic fever; swelling of affected tissues, such as the upper throat during the common cold or joints affected by rheumatoid arthritis; increased production of mucus, which can cause symptoms like a runny nose or a productive cough; pain, inflammatory mediators directly stimulate and sensitize nociceptive nerve endings, resulting in local pain, such as painful joints or a sore throat, or affecting the whole body, such as body aches; and possible dysfunction of involved organs/tissues.', 'Wikipedia: Innate immune system', 'https://en.wikipedia.org/w/index.php?title=Innate_immune_system&oldid=1364464376', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Chemical factors produced during inflammation (histamine, bradykinin, serotonin, leukotrienes, and prostaglandins) sensitize pain receptors, cause local vasodilation of the blood vessels, and attract phagocytes, especially neutrophils. Neutrophils then trigger other parts of the immune system by releasing factors that summon additional leukocytes and lymphocytes. Cytokines produced by macrophages and other cells of the innate immune system mediate the inflammatory response. These cytokines include TNF, HMGB1, and IL-1. heat, either increased local temperature, such as a warm feeling around a localized infection, or a systemic fever; swelling of affected tissues, such as the upper throat during the common cold or joints affected by rheumatoid arthritis; increased production of mucus, which can cause symptoms like a runny nose or a productive cough; pain, inflammatory mediators directly stimulate and sensitize nociceptive nerve endings, resulting in local pain, such as painful joints or a sore throat, or affecting the whole body, such as body aches; and possible dysfunction of involved organs/tissues.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Innate immune system: Complement system', 'The complement system is a key mechanism of innate immunity that utilize proteins to identify and eliminate pathogens, while also maintaining homeostasis by clearing dead and damaged cells. Once a pathogen enters the body through the epithelial barrier, soluble plasma proteins called complement proteins become activated (proteins C1-C9). These complement proteins trigger a cascade of reactions that target and kill extracellular pathogens. In the classical pathway, The antibody in the classical pathway is produced by B cells during the adaptive immune response, and once it binds to a pathogen, it allows C1 to bind and activate the complement system.This then activates C4 and C2 which will both combine to form C3 convertase. C3 convertase will then split into C3a and C3b. C3a aids in promoting opsonization and increases inflammation by helping immune cells move to the infection site, whereas C3b helps in forming a protein complex which functions to insert itself into a pathogen’s membrane to cause cell lysis, killing the pathogen, known as the membrane attack complex, composed of proteins C5b-C9.', 'Wikipedia: Innate immune system', 'https://en.wikipedia.org/w/index.php?title=Innate_immune_system&oldid=1364464376', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The complement system is a key mechanism of innate immunity that utilize proteins to identify and eliminate pathogens, while also maintaining homeostasis by clearing dead and damaged cells. Once a pathogen enters the body through the epithelial barrier, soluble plasma proteins called complement proteins become activated (proteins C1-C9). These complement proteins trigger a cascade of reactions that target and kill extracellular pathogens. In the classical pathway, The antibody in the classical pathway is produced by B cells during the adaptive immune response, and once it binds to a pathogen, it allows C1 to bind and activate the complement system.This then activates C4 and C2 which will both combine to form C3 convertase. C3 convertase will then split into C3a and C3b. C3a aids in promoting opsonization and increases inflammation by helping immune cells move to the infection site, whereas C3b helps in forming a protein complex which functions to insert itself into a pathogen’s membrane to cause cell lysis, killing the pathogen, known as the membrane attack complex, composed of proteins C5b-C9.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Innate immune system: Complement system', 'The alternative pathway follows a similar sequence as the classical pathway but begins with the spontaneous activation of C3. Activated C3 will bind directly to the pathogen’s surface and interacts with other proteins to form C3 convertase. At this point, the pathway will continue like the classical pathway and form the membrane attack complex and kill the pathogen via cell lysis. C3 is mechanistically essential for complement function, and deficiencies in C3 severely impair immune responses. A lack of C3-mediated opsonization is associated with defective dendritic cell differentiation, weakened memory B-cell responses, and impaired regulatory T-cell development, highlighting how C3 influences not only pathogen clearance but also broader adaptive immune processes (Zarantonello, 2022). Elements of the complement cascade can be found in many non-mammalian species including plants, birds, fish, and some species of invertebrates.', 'Wikipedia: Innate immune system', 'https://en.wikipedia.org/w/index.php?title=Innate_immune_system&oldid=1364464376', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The alternative pathway follows a similar sequence as the classical pathway but begins with the spontaneous activation of C3. Activated C3 will bind directly to the pathogen’s surface and interacts with other proteins to form C3 convertase. At this point, the pathway will continue like the classical pathway and form the membrane attack complex and kill the pathogen via cell lysis. C3 is mechanistically essential for complement function, and deficiencies in C3 severely impair immune responses. A lack of C3-mediated opsonization is associated with defective dendritic cell differentiation, weakened memory B-cell responses, and impaired regulatory T-cell development, highlighting how C3 influences not only pathogen clearance but also broader adaptive immune processes (Zarantonello, 2022). Elements of the complement cascade can be found in many non-mammalian species including plants, birds, fish, and some species of invertebrates.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Adaptive immune system', 'The adaptive immune system (AIS), also known as the acquired immune system or specific immune system, is a subsystem of the immune system that is composed of specialized cells, organs, and processes that eliminate pathogens specifically. The acquired immune system is one of the two main immunity strategies found in vertebrates (the other being the innate immune system). Like the innate system, the adaptive immune system includes both humoral immunity components and cell-mediated immunity components and destroys invading pathogens. Unlike the innate immune system, which is pre-programmed to react to common broad categories of pathogen, the adaptive immune system is highly specific to each particular pathogen the body has encountered. Adaptive immunity creates immunological memory after an initial response to a specific pathogen, and leads to an enhanced response to future encounters with that pathogen. Antibodies are a critical part of the adaptive immune system. Adaptive immunity can provide long-lasting protection, sometimes for the person''s entire lifetime. For example, someone who recovers from measles is now protected against measles for their lifetime; in other cases it does not provide lifetime protection, as with chickenpox. This process of adaptive immunity is the basis of vaccination.', 'Wikipedia: Adaptive immune system', 'https://en.wikipedia.org/w/index.php?title=Adaptive_immune_system&oldid=1378627319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The adaptive immune system (AIS), also known as the acquired immune system or specific immune system, is a subsystem of the immune system that is composed of specialized cells, organs, and processes that eliminate pathogens specifically. The acquired immune system is one of the two main immunity strategies found in vertebrates (the other being the innate immune system). Like the innate system, the adaptive immune system includes both humoral immunity components and cell-mediated immunity components and destroys invading pathogens. Unlike the innate immune system, which is pre-programmed to react to common broad categories of pathogen, the adaptive immune system is highly specific to each particular pathogen the body has encountered. Adaptive immunity creates immunological memory after an initial response to a specific pathogen, and leads to an enhanced response to future encounters with that pathogen. Antibodies are a critical part of the adaptive immune system. Adaptive immunity can provide long-lasting protection, sometimes for the person''s entire lifetime. For example, someone who recovers from measles is now protected against measles for their lifetime; in other cases it does not provide lifetime protection, as with chickenpox. This process of adaptive immunity is the basis of vaccination.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Adaptive immune system', 'The cells that carry out the adaptive immune response are white blood cells known as lymphocytes. B cells and T cells, two different types of lymphocytes, carry out the main activities: antibody responses, and cell-mediated immune response. In antibody responses, B cells are activated to secrete antibodies, which are proteins also known as immunoglobulins. Antibodies travel through the bloodstream and bind to the foreign antigen causing it to inactivate, which does not allow the antigen to bind to the host. Antigens are any substances that elicit the adaptive immune response. Sometimes the adaptive system is unable to distinguish harmful from harmless foreign molecules; the effects of this may be hayfever, asthma, or any other allergy. In adaptive immunity, pathogen-specific receptors are "acquired" during the lifetime of the organism (whereas in innate immunity pathogen-specific receptors are already encoded in the genome). This acquired response is called "adaptive" because it prepares the body''s immune system for future challenges (though it can actually also be maladaptive when it results in allergies or autoimmunity).', 'Wikipedia: Adaptive immune system', 'https://en.wikipedia.org/w/index.php?title=Adaptive_immune_system&oldid=1378627319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The cells that carry out the adaptive immune response are white blood cells known as lymphocytes. B cells and T cells, two different types of lymphocytes, carry out the main activities: antibody responses, and cell-mediated immune response. In antibody responses, B cells are activated to secrete antibodies, which are proteins also known as immunoglobulins. Antibodies travel through the bloodstream and bind to the foreign antigen causing it to inactivate, which does not allow the antigen to bind to the host. Antigens are any substances that elicit the adaptive immune response. Sometimes the adaptive system is unable to distinguish harmful from harmless foreign molecules; the effects of this may be hayfever, asthma, or any other allergy. In adaptive immunity, pathogen-specific receptors are "acquired" during the lifetime of the organism (whereas in innate immunity pathogen-specific receptors are already encoded in the genome). This acquired response is called "adaptive" because it prepares the body''s immune system for future challenges (though it can actually also be maladaptive when it results in allergies or autoimmunity).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Adaptive immune system', 'The system is highly adaptable because of two factors. First, somatic hypermutation is a process of accelerated random genetic mutations in the antibody-coding genes, which allows antibodies with novel specificity to be created. Second, V(D)J recombination randomly selects one variable (V), one diversity (D), and one joining (J) region for genetic recombination and discards the rest, which produces a highly unique combination of antigen-receptor gene segments in each lymphocyte. This mechanism allows a small number of genetic segments to generate a vast number of different antigen receptors, which are then uniquely expressed on each individual lymphocyte. Since the gene rearrangement leads to an irreversible change in the DNA of each cell, all progeny (offspring) of that cell inherit genes that encode the same receptor specificity, including the memory B cells and memory T cells that are the keys to long-lived specific immunity.', 'Wikipedia: Adaptive immune system', 'https://en.wikipedia.org/w/index.php?title=Adaptive_immune_system&oldid=1378627319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The system is highly adaptable because of two factors. First, somatic hypermutation is a process of accelerated random genetic mutations in the antibody-coding genes, which allows antibodies with novel specificity to be created. Second, V(D)J recombination randomly selects one variable (V), one diversity (D), and one joining (J) region for genetic recombination and discards the rest, which produces a highly unique combination of antigen-receptor gene segments in each lymphocyte. This mechanism allows a small number of genetic segments to generate a vast number of different antigen receptors, which are then uniquely expressed on each individual lymphocyte. Since the gene rearrangement leads to an irreversible change in the DNA of each cell, all progeny (offspring) of that cell inherit genes that encode the same receptor specificity, including the memory B cells and memory T cells that are the keys to long-lived specific immunity.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Adaptive immune system: Naming', 'The term "adaptive" was first used by Robert Good in reference to antibody responses in frogs as a synonym for "acquired immune response" in 1964. Good acknowledged he used the terms as synonyms but explained only that he preferred to use the term "adaptive". He might have been thinking of the then not implausible theory of antibody formation in which antibodies were plastic and could adapt themselves to the molecular shape of antigens, and/or to the concept of "adaptive enzymes" as described by Monod in bacteria, that is, enzymes whose expression could be induced by their substrates. The phrase was used almost exclusively by Good and his students and a few other immunologists working with marginal organisms until the 1990s when it became widely used in tandem with the term "innate immunity" which became a popular subject after the discovery of the Toll receptor system in Drosophila, a previously marginal organism for the study of immunology. The term "adaptive" as used in immunology is problematic as acquired immune responses can be both adaptive and maladaptive in the physiological sense. Indeed, both acquired and innate immune responses can be both adaptive and maladaptive in the evolutionary sense. Most textbooks today, following the early use by Janeway, use "adaptive" almost exclusively and noting in glossaries that the term is synonymous with "acquired".', 'Wikipedia: Adaptive immune system', 'https://en.wikipedia.org/w/index.php?title=Adaptive_immune_system&oldid=1378627319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The term "adaptive" was first used by Robert Good in reference to antibody responses in frogs as a synonym for "acquired immune response" in 1964. Good acknowledged he used the terms as synonyms but explained only that he preferred to use the term "adaptive". He might have been thinking of the then not implausible theory of antibody formation in which antibodies were plastic and could adapt themselves to the molecular shape of antigens, and/or to the concept of "adaptive enzymes" as described by Monod in bacteria, that is, enzymes whose expression could be induced by their substrates. The phrase was used almost exclusively by Good and his students and a few other immunologists working with marginal organisms until the 1990s when it became widely used in tandem with the term "innate immunity" which became a popular subject after the discovery of the Toll receptor system in Drosophila, a previously marginal organism for the study of immunology. The term "adaptive" as used in immunology is problematic as acquired immune responses can be both adaptive and maladaptive in the physiological sense. Indeed, both acquired and innate immune responses can be both adaptive and maladaptive in the evolutionary sense. Most textbooks today, following the early use by Janeway, use "adaptive" almost exclusively and noting in glossaries that the term is synonymous with "acquired".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Adaptive immune system: Naming', 'The classic sense of "acquired immunity" came to mean, since Tonegawa''s discovery, "antigen-specific immunity mediated by somatic gene rearrangements that create clone-defining antigen receptors". In the last decade, the term "adaptive" has been increasingly applied to another class of immune response not so-far associated with somatic gene rearrangements. These include expansion of natural killer (NK) cells with so-far unexplained specificity for antigens, expansion of NK cells expressing germ-line encoded receptors, and activation of other innate immune cells to an activated state that confers a short-term "immune memory". In this sense, "adaptive immunity" more closely resembles the concept of "activated state" or "heterostasis", thus returning in sense to the physiological sense of "adaptation" to environmental changes.', 'Wikipedia: Adaptive immune system', 'https://en.wikipedia.org/w/index.php?title=Adaptive_immune_system&oldid=1378627319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The classic sense of "acquired immunity" came to mean, since Tonegawa''s discovery, "antigen-specific immunity mediated by somatic gene rearrangements that create clone-defining antigen receptors". In the last decade, the term "adaptive" has been increasingly applied to another class of immune response not so-far associated with somatic gene rearrangements. These include expansion of natural killer (NK) cells with so-far unexplained specificity for antigens, expansion of NK cells expressing germ-line encoded receptors, and activation of other innate immune cells to an activated state that confers a short-term "immune memory". In this sense, "adaptive immunity" more closely resembles the concept of "activated state" or "heterostasis", thus returning in sense to the physiological sense of "adaptation" to environmental changes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Adaptive immune system: Functions', 'Acquired immunity is triggered in vertebrates when a pathogen evades the innate immune system and (1) generates a threshold level of antigen and (2) generates "stranger" or "danger" signals activating dendritic cells. Recognition of specific "non-self" antigens in the presence of "self", during the process of antigen presentation. Generation of responses that are tailored to maximally eliminate specific pathogens or pathogen-infected cells. Development of immunological memory, in which pathogens are "remembered" through memory B cells and memory T cells. In humans, it takes 4–7 days for the adaptive immune system to mount a significant response.', 'Wikipedia: Adaptive immune system', 'https://en.wikipedia.org/w/index.php?title=Adaptive_immune_system&oldid=1378627319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Acquired immunity is triggered in vertebrates when a pathogen evades the innate immune system and (1) generates a threshold level of antigen and (2) generates "stranger" or "danger" signals activating dendritic cells. Recognition of specific "non-self" antigens in the presence of "self", during the process of antigen presentation. Generation of responses that are tailored to maximally eliminate specific pathogens or pathogen-infected cells. Development of immunological memory, in which pathogens are "remembered" through memory B cells and memory T cells. In humans, it takes 4–7 days for the adaptive immune system to mount a significant response.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Adaptive immune system: Lymphocytes', 'T and B lymphocytes are the cells of the adaptive immune system. The human body has about 2 trillion lymphocytes, which are 20–40% of white blood cells; their total mass is about the same as the brain or liver. The peripheral bloodstream contains only 2% of all circulating lymphocytes; the other 98% move within tissues and the lymphatic system, which includes the lymph nodes and spleen. In humans, approximately 1–2% of the lymphocyte pool recirculates each hour to increase the opportunity for the cells to encounter the specific pathogen and antigen that they react to. B cells and T cells are derived from the same multipotent hematopoietic stem cells, and look identical to one another until after they are activated. B cells play a large role in the humoral immune response, whereas T cells are intimately involved in cell-mediated immune responses. In all vertebrates except Agnatha, B cells and T cells are produced by stem cells in the bone marrow. T cell progenitors then migrate from the bone marrow to the thymus, where they develop further. In an adult animal, the peripheral lymphoid organs contain a mixture of B and T cells in at least three stages of differentiation:', 'Wikipedia: Adaptive immune system', 'https://en.wikipedia.org/w/index.php?title=Adaptive_immune_system&oldid=1378627319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'T and B lymphocytes are the cells of the adaptive immune system. The human body has about 2 trillion lymphocytes, which are 20–40% of white blood cells; their total mass is about the same as the brain or liver. The peripheral bloodstream contains only 2% of all circulating lymphocytes; the other 98% move within tissues and the lymphatic system, which includes the lymph nodes and spleen. In humans, approximately 1–2% of the lymphocyte pool recirculates each hour to increase the opportunity for the cells to encounter the specific pathogen and antigen that they react to. B cells and T cells are derived from the same multipotent hematopoietic stem cells, and look identical to one another until after they are activated. B cells play a large role in the humoral immune response, whereas T cells are intimately involved in cell-mediated immune responses. In all vertebrates except Agnatha, B cells and T cells are produced by stem cells in the bone marrow. T cell progenitors then migrate from the bone marrow to the thymus, where they develop further. In an adult animal, the peripheral lymphoid organs contain a mixture of B and T cells in at least three stages of differentiation:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Adaptive immune system: Lymphocytes', 'Naive B and naive T cells, which have left the bone marrow or thymus and entered the lymphatic system, but have yet to encounter their matching antigen Effector cells that have been activated by their matching antigen, and are actively involved in eliminating a pathogen', 'Wikipedia: Adaptive immune system', 'https://en.wikipedia.org/w/index.php?title=Adaptive_immune_system&oldid=1378627319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Naive B and naive T cells, which have left the bone marrow or thymus and entered the lymphatic system, but have yet to encounter their matching antigen Effector cells that have been activated by their matching antigen, and are actively involved in eliminating a pathogen');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Antibody', 'An antibody (Ab), or immunoglobulin (Ig), is a large protein belonging to the immunoglobulin superfamily which is used by the immune system to identify and neutralize antigens such as those that exist on bacteria and virus cells, including those that cause disease. Each individual antibody recognizes one or more specific antigens, and antigens (a portmanteau of "antibody generator") of virtually any size and chemical composition can be recognized. Each of the branching chains comprising the "Y" of an antibody contains a paratope (the antigen-binding site) that specifically binds to one particular epitope (a specific part of an antigen bound by the paratope) on an antigen, allowing the two molecules to bind together with precision. Using this mechanism, antibodies can effectively "tag" the antigen (or a microbe or an infected cell bearing such an antigen) for attack by cells of the immune system, or can neutralize it directly (for example, by blocking a part of a virus that is essential for its ability to invade a host cell).', 'Wikipedia: Antibody', 'https://en.wikipedia.org/w/index.php?title=Antibody&oldid=1379707520', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'An antibody (Ab), or immunoglobulin (Ig), is a large protein belonging to the immunoglobulin superfamily which is used by the immune system to identify and neutralize antigens such as those that exist on bacteria and virus cells, including those that cause disease. Each individual antibody recognizes one or more specific antigens, and antigens (a portmanteau of "antibody generator") of virtually any size and chemical composition can be recognized. Each of the branching chains comprising the "Y" of an antibody contains a paratope (the antigen-binding site) that specifically binds to one particular epitope (a specific part of an antigen bound by the paratope) on an antigen, allowing the two molecules to bind together with precision. Using this mechanism, antibodies can effectively "tag" the antigen (or a microbe or an infected cell bearing such an antigen) for attack by cells of the immune system, or can neutralize it directly (for example, by blocking a part of a virus that is essential for its ability to invade a host cell).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Antibody', 'Antibodies may be borne on the surface of an immune cell, as in a B cell receptor, or they may exist freely by being secreted into the extracellular space. The term antibody generally refers to the free (secreted) form, while the term immunoglobulin can refer to either form. Since they are, broadly speaking, the same protein, the terms are often treated as synonymous.', 'Wikipedia: Antibody', 'https://en.wikipedia.org/w/index.php?title=Antibody&oldid=1379707520', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Antibodies may be borne on the surface of an immune cell, as in a B cell receptor, or they may exist freely by being secreted into the extracellular space. The term antibody generally refers to the free (secreted) form, while the term immunoglobulin can refer to either form. Since they are, broadly speaking, the same protein, the terms are often treated as synonymous.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Antibody', 'To allow the immune system to recognize millions of different antigens, the antigen-binding paratopes at each tip of the antibody come in an equally wide variety. The rest of an antibody''s structure is much less variable; in humans, antibodies occur in five classes or isotypes: IgA, IgD, IgE, IgG, and IgM. Human IgG and IgA antibodies are also divided into discrete subclasses (IgG1, IgG2, IgG3, and IgG4; IgA1 and IgA2). The class refers to the functions triggered by the antibody (also known as effector functions), in addition to some other structural features. Antibodies from different classes also differ in where they are released in the body and at what stage of an immune response. Between species, while classes and subclasses of antibodies may be shared (at least in name), their function and distribution throughout the body may be different, which complicates the use of animal models in studying antibodies. For example, mouse IgG1 is closer to human IgG2 than to human IgG1 in terms of its function.', 'Wikipedia: Antibody', 'https://en.wikipedia.org/w/index.php?title=Antibody&oldid=1379707520', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'To allow the immune system to recognize millions of different antigens, the antigen-binding paratopes at each tip of the antibody come in an equally wide variety. The rest of an antibody''s structure is much less variable; in humans, antibodies occur in five classes or isotypes: IgA, IgD, IgE, IgG, and IgM. Human IgG and IgA antibodies are also divided into discrete subclasses (IgG1, IgG2, IgG3, and IgG4; IgA1 and IgA2). The class refers to the functions triggered by the antibody (also known as effector functions), in addition to some other structural features. Antibodies from different classes also differ in where they are released in the body and at what stage of an immune response. Between species, while classes and subclasses of antibodies may be shared (at least in name), their function and distribution throughout the body may be different, which complicates the use of animal models in studying antibodies. For example, mouse IgG1 is closer to human IgG2 than to human IgG1 in terms of its function.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Antibody', 'The term humoral immunity is often treated as synonymous with the antibody response, describing the function of the immune system that exists in the body''s humors (fluids) in the form of soluble proteins, as distinct from cell-mediated immunity, which generally describes the responses of T cells (especially killer T cells). In general, antibodies are considered part of the adaptive immune system, though this classification can become complicated. For example, natural IgM, which are made by B-1 cells that have properties more similar to innate immune cells than adaptive, refers to IgM antibodies made independently of an immune response that demonstrate polyreactivity—i.e. they recognize multiple distinct (unrelated) antigens. These can work with the complement system in the earliest phases of an immune response to help facilitate clearance of the offending antigen and delivery of the resulting immune complexes to the lymph nodes or spleen for initiation of an immune response. Hence in this capacity, the functions of antibodies are more akin to that of innate immunity than adaptive. Nonetheless, in general, antibodies are regarded as part of the adaptive immune system because they demonstrate exceptional specificity (with some exceptions), are produced through genetic rearrangements (rather than being encoded directly in the germline), and are a manifestation of immunological memory.', 'Wikipedia: Antibody', 'https://en.wikipedia.org/w/index.php?title=Antibody&oldid=1379707520', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The term humoral immunity is often treated as synonymous with the antibody response, describing the function of the immune system that exists in the body''s humors (fluids) in the form of soluble proteins, as distinct from cell-mediated immunity, which generally describes the responses of T cells (especially killer T cells). In general, antibodies are considered part of the adaptive immune system, though this classification can become complicated. For example, natural IgM, which are made by B-1 cells that have properties more similar to innate immune cells than adaptive, refers to IgM antibodies made independently of an immune response that demonstrate polyreactivity—i.e. they recognize multiple distinct (unrelated) antigens. These can work with the complement system in the earliest phases of an immune response to help facilitate clearance of the offending antigen and delivery of the resulting immune complexes to the lymph nodes or spleen for initiation of an immune response. Hence in this capacity, the functions of antibodies are more akin to that of innate immunity than adaptive. Nonetheless, in general, antibodies are regarded as part of the adaptive immune system because they demonstrate exceptional specificity (with some exceptions), are produced through genetic rearrangements (rather than being encoded directly in the germline), and are a manifestation of immunological memory.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Antibody: Sources of antibodies', 'Antibodies arise from antibody-secreting cells, a term that encompasses plasmablasts and plasma cells. B cells themselves are not able to secrete antibody and can only present immunoglobulins on their surface because they do not express the critical transcription factor BLIMP-1, which establishes the antibody-secreting cell transcriptional program (including altering alternative splicing and polyadenylation to generate the secreted form of the immunoglobulin heavy chain rather than the membrane-bound one; secretion of antibody is not protease-dependent).', 'Wikipedia: Antibody', 'https://en.wikipedia.org/w/index.php?title=Antibody&oldid=1379707520', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Antibodies arise from antibody-secreting cells, a term that encompasses plasmablasts and plasma cells. B cells themselves are not able to secrete antibody and can only present immunoglobulins on their surface because they do not express the critical transcription factor BLIMP-1, which establishes the antibody-secreting cell transcriptional program (including altering alternative splicing and polyadenylation to generate the secreted form of the immunoglobulin heavy chain rather than the membrane-bound one; secretion of antibody is not protease-dependent).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Antibody: Sources of antibodies', 'In the course of an immune response, B cells can progressively differentiate into antibody-secreting cells or into memory B cells. Plasmablasts and plasma cells differ mainly in the degree to which they secrete antibodies, their lifespan, metabolic adaptations, and surface markers. Plasmablasts are rapidly proliferating, short-lived cells produced in the early phases of the immune response (classically described as arising from extrafollicular reactions rather than from a germinal center) which have the potential to differentiate further into plasma cells. Occasionally plasmablasts are mis-described as short-lived plasma cells; formally this is incorrect because plasma cells do not divide (they are terminally differentiated), and rely on survival niches comprising specific cell types and cytokines to persist. It is commonly said that plasma cells do not express surface immunoglobulin (whereas plasmablasts do), but this depends on the class of antibody that the plasma cell generates (IgG-secreting plasma cells do not, but IgM, IgA, and IgE plasma cells do). Plasma cells will secrete huge quantities of antibody regardless of whether or not antigen is present, ensuring that antibody levels to the antigen in question do not fall to zero, provided the plasma cell stays alive. The rate of antibody secretion, however, can be regulated, for example, by the presence of adjuvant molecules that stimulate the immune response such as toll-like receptor ligands. Long-lived plasma cells can live for potentially the entire lifetime of the organism. Classically, the survival niches that house long-lived plasma cells reside in the bone marrow, though it cannot be assumed that any given plasma cell in the bone marrow will be long-lived. However, other work indicates that survival niches can readily be established within the mucosal tissues, though the classes of antibodies involved show a different hierarchy from those in the bone marrow.', 'Wikipedia: Antibody', 'https://en.wikipedia.org/w/index.php?title=Antibody&oldid=1379707520', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'In the course of an immune response, B cells can progressively differentiate into antibody-secreting cells or into memory B cells. Plasmablasts and plasma cells differ mainly in the degree to which they secrete antibodies, their lifespan, metabolic adaptations, and surface markers. Plasmablasts are rapidly proliferating, short-lived cells produced in the early phases of the immune response (classically described as arising from extrafollicular reactions rather than from a germinal center) which have the potential to differentiate further into plasma cells. Occasionally plasmablasts are mis-described as short-lived plasma cells; formally this is incorrect because plasma cells do not divide (they are terminally differentiated), and rely on survival niches comprising specific cell types and cytokines to persist. It is commonly said that plasma cells do not express surface immunoglobulin (whereas plasmablasts do), but this depends on the class of antibody that the plasma cell generates (IgG-secreting plasma cells do not, but IgM, IgA, and IgE plasma cells do). Plasma cells will secrete huge quantities of antibody regardless of whether or not antigen is present, ensuring that antibody levels to the antigen in question do not fall to zero, provided the plasma cell stays alive. The rate of antibody secretion, however, can be regulated, for example, by the presence of adjuvant molecules that stimulate the immune response such as toll-like receptor ligands. Long-lived plasma cells can live for potentially the entire lifetime of the organism. Classically, the survival niches that house long-lived plasma cells reside in the bone marrow, though it cannot be assumed that any given plasma cell in the bone marrow will be long-lived. However, other work indicates that survival niches can readily be established within the mucosal tissues, though the classes of antibodies involved show a different hierarchy from those in the bone marrow.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Antibody: Sources of antibodies', 'B cells can also differentiate into memory B cells which can persist for decades, similarly to long-lived plasma cells. These cells can be rapidly recalled in a secondary immune response, undergoing class switching, affinity maturation, and differentiating into antibody-secreting cells.', 'Wikipedia: Antibody', 'https://en.wikipedia.org/w/index.php?title=Antibody&oldid=1379707520', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'B cells can also differentiate into memory B cells which can persist for decades, similarly to long-lived plasma cells. These cells can be rapidly recalled in a secondary immune response, undergoing class switching, affinity maturation, and differentiating into antibody-secreting cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Antibody: Structure', 'Antibodies are heavy (~150 kDa) proteins of about 10 nm in size, In humans and most other mammals, an antibody unit consists of four polypeptide chains; two identical heavy chains and two identical light chains connected by disulfide bonds. Each chain is a series of domains: somewhat similar sequences of about 110 amino acids each. Light chains consist of one variable domain VL and one constant domain CL, while heavy chains contain one variable domain VH and three to four constant domains CH1, CH2,... Structurally an antibody is also partitioned into two antigen-binding fragments (Fab), containing one VL, VH, CL, and CH1 domain each, as well as the crystallisable fragment (Fc), forming the trunk of the Y shape. In between them is a hinge region of the heavy chains, whose flexibility allows antibodies to bind to pairs of epitopes at various distances, to form complexes (dimers, trimers, etc.), and to bind effector molecules more easily. In an electrophoresis test of blood proteins, antibodies mostly migrate to the last, gamma globulin fraction. Conversely, most gamma-globulins are antibodies, which is why the two terms were historically used as synonyms, as were the symbols Ig and γ.', 'Wikipedia: Antibody', 'https://en.wikipedia.org/w/index.php?title=Antibody&oldid=1379707520', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Antibodies are heavy (~150 kDa) proteins of about 10 nm in size, In humans and most other mammals, an antibody unit consists of four polypeptide chains; two identical heavy chains and two identical light chains connected by disulfide bonds. Each chain is a series of domains: somewhat similar sequences of about 110 amino acids each. Light chains consist of one variable domain VL and one constant domain CL, while heavy chains contain one variable domain VH and three to four constant domains CH1, CH2,... Structurally an antibody is also partitioned into two antigen-binding fragments (Fab), containing one VL, VH, CL, and CH1 domain each, as well as the crystallisable fragment (Fc), forming the trunk of the Y shape. In between them is a hinge region of the heavy chains, whose flexibility allows antibodies to bind to pairs of epitopes at various distances, to form complexes (dimers, trimers, etc.), and to bind effector molecules more easily. In an electrophoresis test of blood proteins, antibodies mostly migrate to the last, gamma globulin fraction. Conversely, most gamma-globulins are antibodies, which is why the two terms were historically used as synonyms, as were the symbols Ig and γ.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'T cell', 'T cells (also known as T lymphocytes) are an important part of the immune system and play a central role in the adaptive immune response. T cells can be distinguished from other lymphocytes by the presence of a T-cell receptor (TCR) on their cell surface. T cells are born from hematopoietic stem cells, found in the bone marrow. Developing T cells then migrate to the thymus gland to develop (or mature). T cells derive their name from the thymus. After migration to the thymus, getting stimulated by thymosin, the precursor cells mature into several distinct types of T cells. T cell differentiation also continues after they have left the thymus. Groups of specific, differentiated T cell subtypes have a variety of important functions in controlling and shaping the immune response.', 'Wikipedia: T cell', 'https://en.wikipedia.org/w/index.php?title=T_cell&oldid=1371316772', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'T cells (also known as T lymphocytes) are an important part of the immune system and play a central role in the adaptive immune response. T cells can be distinguished from other lymphocytes by the presence of a T-cell receptor (TCR) on their cell surface. T cells are born from hematopoietic stem cells, found in the bone marrow. Developing T cells then migrate to the thymus gland to develop (or mature). T cells derive their name from the thymus. After migration to the thymus, getting stimulated by thymosin, the precursor cells mature into several distinct types of T cells. T cell differentiation also continues after they have left the thymus. Groups of specific, differentiated T cell subtypes have a variety of important functions in controlling and shaping the immune response.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'T cell', 'One of these functions is immune-mediated cell death, and it is carried out by two major subtypes: CD8+ "killer" (cytotoxic, Effector tumor antigen-specific T cells) and CD4+ "helper" T cells, each respectively named for the presence of proteins CD8 or CD4 on the cell surface. CD8+ T cells, also known as "killer T cells," are cytotoxic, referring to their ability to directly kill virus-infected cells and cancer cells. CD8+ T cells are also able to use small signalling proteins, known as cytokines, to recruit other types of cells when mounting an immune response. On the other hand, CD4+ T cells function as "helper cells." Unlike CD8+ killer T cells, the CD4+ helper T (TH) cells function by further activating memory B cells and cytotoxic T cells, which leads to a larger immune response. The specific adaptive immune response regulated by the TH cell depends on its subtype (i.e., T-helper1, T-helper2, T-helper17, and regulatory T-cell), which is distinguished by the types of cytokines they secrete.', 'Wikipedia: T cell', 'https://en.wikipedia.org/w/index.php?title=T_cell&oldid=1371316772', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'One of these functions is immune-mediated cell death, and it is carried out by two major subtypes: CD8+ "killer" (cytotoxic, Effector tumor antigen-specific T cells) and CD4+ "helper" T cells, each respectively named for the presence of proteins CD8 or CD4 on the cell surface. CD8+ T cells, also known as "killer T cells," are cytotoxic, referring to their ability to directly kill virus-infected cells and cancer cells. CD8+ T cells are also able to use small signalling proteins, known as cytokines, to recruit other types of cells when mounting an immune response. On the other hand, CD4+ T cells function as "helper cells." Unlike CD8+ killer T cells, the CD4+ helper T (TH) cells function by further activating memory B cells and cytotoxic T cells, which leads to a larger immune response. The specific adaptive immune response regulated by the TH cell depends on its subtype (i.e., T-helper1, T-helper2, T-helper17, and regulatory T-cell), which is distinguished by the types of cytokines they secrete.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'T cell', 'Regulatory T cells are yet another distinct population of T cells that provide the critical mechanism of tolerance, whereby immune cells are able to distinguish invading cells from "self." This prevents immune cells from inappropriately reacting against one''s own cells, known as an autoimmune response. For this reason, these regulatory T cells have also been called "suppressor" T cells. These same regulatory T cells can also be co-opted by cancer cells to prevent the recognition of, and an immune response against, tumor cells.', 'Wikipedia: T cell', 'https://en.wikipedia.org/w/index.php?title=T_cell&oldid=1371316772', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Regulatory T cells are yet another distinct population of T cells that provide the critical mechanism of tolerance, whereby immune cells are able to distinguish invading cells from "self." This prevents immune cells from inappropriately reacting against one''s own cells, known as an autoimmune response. For this reason, these regulatory T cells have also been called "suppressor" T cells. These same regulatory T cells can also be co-opted by cancer cells to prevent the recognition of, and an immune response against, tumor cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'T cell: Origin, early development and migration to the thymus', 'All T cells originate from c-kit+Sca1+ haematopoietic stem cells (HSC) that reside in the bone marrow. In some cases, the origin might be the foetal liver during embryonic development. The HSC then differentiate into multipotent progenitors (MPP) which retain the potential to become both myeloid and lymphoid cells. The process of differentiation then proceeds to a common lymphoid progenitor (CLP), which can only differentiate into T, B, or NK cells. These CLP cells then migrate via the blood to the thymus, where they engraft. Henceforth they are known as thymocytes, the immature stage of a T cell. The earliest cells which arrived in the thymus are commonly termed double-negative, as they express neither the CD4 nor CD8 co-receptor. The newly arrived CLP cells are CD4−CD8−CD44+CD25−ckit+ cells, and are termed early thymic progenitor (ETP) cells. These cells will then undergo a round of division and downregulate c-kit and are termed double-negative one (DN1) cells. To become T cells, the thymocytes must undergo multiple DN stages as well as positive selection and negative selection. Double negative thymocytes can be identified by the surface expression of CD2, CD5, and CD7. Still during the double negative stages, CD34 expression stops and CD1 is expressed. Expression of both CD4 and CD8 makes them double positive, and matures into either CD4+ or CD8+ cells.', 'Wikipedia: T cell', 'https://en.wikipedia.org/w/index.php?title=T_cell&oldid=1371316772', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'All T cells originate from c-kit+Sca1+ haematopoietic stem cells (HSC) that reside in the bone marrow. In some cases, the origin might be the foetal liver during embryonic development. The HSC then differentiate into multipotent progenitors (MPP) which retain the potential to become both myeloid and lymphoid cells. The process of differentiation then proceeds to a common lymphoid progenitor (CLP), which can only differentiate into T, B, or NK cells. These CLP cells then migrate via the blood to the thymus, where they engraft. Henceforth they are known as thymocytes, the immature stage of a T cell. The earliest cells which arrived in the thymus are commonly termed double-negative, as they express neither the CD4 nor CD8 co-receptor. The newly arrived CLP cells are CD4−CD8−CD44+CD25−ckit+ cells, and are termed early thymic progenitor (ETP) cells. These cells will then undergo a round of division and downregulate c-kit and are termed double-negative one (DN1) cells. To become T cells, the thymocytes must undergo multiple DN stages as well as positive selection and negative selection. Double negative thymocytes can be identified by the surface expression of CD2, CD5, and CD7. Still during the double negative stages, CD34 expression stops and CD1 is expressed. Expression of both CD4 and CD8 makes them double positive, and matures into either CD4+ or CD8+ cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'T cell: TCR development', 'A critical step in T cell maturation is making a functional T cell receptor (TCR). Each mature T cell will ultimately contain a unique TCR that reacts to a random pattern, allowing the immune system to recognize many different types of pathogens. This process is essential in developing immunity to threats that the immune system has not encountered before, since due to random variation there will always be at least one TCR to match any new pathogen.', 'Wikipedia: T cell', 'https://en.wikipedia.org/w/index.php?title=T_cell&oldid=1371316772', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'A critical step in T cell maturation is making a functional T cell receptor (TCR). Each mature T cell will ultimately contain a unique TCR that reacts to a random pattern, allowing the immune system to recognize many different types of pathogens. This process is essential in developing immunity to threats that the immune system has not encountered before, since due to random variation there will always be at least one TCR to match any new pathogen.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'T cell: TCR development', 'A thymocyte can only become an active T cell when it survives the process of developing a functional TCR. The TCR consists of two major components, the alpha and beta chains. These both contain random elements designed to produce a wide variety of different TCRs, but due to this huge variety they must be tested to make sure they work at all. First, the thymocytes attempt to create a functional beta chain, testing it against a ''mock'' alpha chain. Then they attempt to create a functional alpha chain. Once a working TCR has been produced, the cells then must test if their TCR will identify threats correctly, and to do this it is required to recognize the body''s major histocompatibility complex (MHC) in a process known as positive selection. The thymocyte must also ensure that it does not react adversely to "self" antigens, called negative selection. If both positive and negative selection are successful, the TCR becomes fully operational and the thymocyte becomes a T cell.', 'Wikipedia: T cell', 'https://en.wikipedia.org/w/index.php?title=T_cell&oldid=1371316772', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'A thymocyte can only become an active T cell when it survives the process of developing a functional TCR. The TCR consists of two major components, the alpha and beta chains. These both contain random elements designed to produce a wide variety of different TCRs, but due to this huge variety they must be tested to make sure they work at all. First, the thymocytes attempt to create a functional beta chain, testing it against a ''mock'' alpha chain. Then they attempt to create a functional alpha chain. Once a working TCR has been produced, the cells then must test if their TCR will identify threats correctly, and to do this it is required to recognize the body''s major histocompatibility complex (MHC) in a process known as positive selection. The thymocyte must also ensure that it does not react adversely to "self" antigens, called negative selection. If both positive and negative selection are successful, the TCR becomes fully operational and the thymocyte becomes a T cell.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'T cell: TCR β-chain selection', 'At the DN2 stage (CD44+CD25+), cells upregulate the recombination genes RAG1 and RAG2 and re-arrange the TCRβ locus, combining V-D-J recombination and constant region genes in an attempt to create a functional TCRβ chain. As the developing thymocyte progresses through to the DN3 stage (CD44−CD25+), the thymocyte expresses an invariant α-chain called pre-Tα alongside the TCRβ gene. If the rearranged β-chain successfully pairs with the invariant α-chain, signals are produced which cease rearrangement of the β-chain (and silence the alternate allele). Although these signals require the pre-TCR at the cell surface, they are independent of ligand binding to the pre-TCR. If the chains successfully pair a pre-TCR forms, and the cell downregulates CD25 and is termed a DN4 cell (CD25−CD44−). These cells then undergo a round of proliferation, and begin to re-arrange the TCRα locus during the double-positive stage.', 'Wikipedia: T cell', 'https://en.wikipedia.org/w/index.php?title=T_cell&oldid=1371316772', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'At the DN2 stage (CD44+CD25+), cells upregulate the recombination genes RAG1 and RAG2 and re-arrange the TCRβ locus, combining V-D-J recombination and constant region genes in an attempt to create a functional TCRβ chain. As the developing thymocyte progresses through to the DN3 stage (CD44−CD25+), the thymocyte expresses an invariant α-chain called pre-Tα alongside the TCRβ gene. If the rearranged β-chain successfully pairs with the invariant α-chain, signals are produced which cease rearrangement of the β-chain (and silence the alternate allele). Although these signals require the pre-TCR at the cell surface, they are independent of ligand binding to the pre-TCR. If the chains successfully pair a pre-TCR forms, and the cell downregulates CD25 and is termed a DN4 cell (CD25−CD44−). These cells then undergo a round of proliferation, and begin to re-arrange the TCRα locus during the double-positive stage.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'T cell: Positive selection', 'The process of positive selection takes 3 to 4 days and occurs in the thymic cortex. Double-positive thymocytes (CD4+/CD8+) migrate deep into the thymic cortex, where they are presented with self-antigens. These self-antigens are expressed by thymic cortical epithelial cells on MHC molecules, which reside on the surface of cortical epithelial cells. Only thymocytes that interact well with MHC-I or MHC-II will receive a vital "survival signal", while those that cannot interact strongly enough will receive no signal and die from neglect. This process ensures that the surviving thymocytes will have an ''MHC affinity'' that means they will exhibit stronger binding affinity for specific MHC alleles in that organism. The vast majority of developing thymocytes will not pass positive selection, and die during this process. A thymocyte''s fate is determined during positive selection. Double-positive cells (CD4+/CD8+) that interact well with MHC class II molecules will eventually become CD4+ "helper" cells, whereas thymocytes that interact well with MHC class I molecules mature into CD8+ "killer" cells. A thymocyte becomes a CD4+ cell by down-regulating expression of its CD8 cell surface receptors. If the cell does not lose its signal, it will continue downregulating CD8 and become a CD4+, both CD8+ and CD4+ cells are now single positive cells.', 'Wikipedia: T cell', 'https://en.wikipedia.org/w/index.php?title=T_cell&oldid=1371316772', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The process of positive selection takes 3 to 4 days and occurs in the thymic cortex. Double-positive thymocytes (CD4+/CD8+) migrate deep into the thymic cortex, where they are presented with self-antigens. These self-antigens are expressed by thymic cortical epithelial cells on MHC molecules, which reside on the surface of cortical epithelial cells. Only thymocytes that interact well with MHC-I or MHC-II will receive a vital "survival signal", while those that cannot interact strongly enough will receive no signal and die from neglect. This process ensures that the surviving thymocytes will have an ''MHC affinity'' that means they will exhibit stronger binding affinity for specific MHC alleles in that organism. The vast majority of developing thymocytes will not pass positive selection, and die during this process. A thymocyte''s fate is determined during positive selection. Double-positive cells (CD4+/CD8+) that interact well with MHC class II molecules will eventually become CD4+ "helper" cells, whereas thymocytes that interact well with MHC class I molecules mature into CD8+ "killer" cells. A thymocyte becomes a CD4+ cell by down-regulating expression of its CD8 cell surface receptors. If the cell does not lose its signal, it will continue downregulating CD8 and become a CD4+, both CD8+ and CD4+ cells are now single positive cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Major histocompatibility complex', 'The major histocompatibility complex (MHC) is a large locus on vertebrate DNA containing a set of closely linked polymorphic genes that code for cell surface proteins essential for the adaptive immune system. These cell surface proteins are called MHC molecules. Its name comes from its discovery during the study of transplanted tissue compatibility. Later studies revealed that tissue rejection due to incompatibility is only a facet of the full function of MHC molecules, which is to bind an antigen derived from self-proteins, or from pathogens, and bring the antigen presentation to the cell surface for recognition by the appropriate T-cells. MHC molecules mediate the interactions of leukocytes, also called white blood cells (WBCs), with other leukocytes or with body cells. The MHC determines donor compatibility for organ transplant, as well as one''s susceptibility to autoimmune diseases. In a cell, protein molecules of the host''s own phenotype or of other biologic entities are continually synthesized and degraded. Each MHC molecule on the cell surface displays a small peptide (a molecular fraction of a protein) called an epitope. The presented self-antigens prevent an organism''s immune system from targeting its own cells. The presentation of pathogen-derived proteins results in the elimination of the infected cell by the immune system.', 'Wikipedia: Major histocompatibility complex', 'https://en.wikipedia.org/w/index.php?title=Major_histocompatibility_complex&oldid=1379602815', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The major histocompatibility complex (MHC) is a large locus on vertebrate DNA containing a set of closely linked polymorphic genes that code for cell surface proteins essential for the adaptive immune system. These cell surface proteins are called MHC molecules. Its name comes from its discovery during the study of transplanted tissue compatibility. Later studies revealed that tissue rejection due to incompatibility is only a facet of the full function of MHC molecules, which is to bind an antigen derived from self-proteins, or from pathogens, and bring the antigen presentation to the cell surface for recognition by the appropriate T-cells. MHC molecules mediate the interactions of leukocytes, also called white blood cells (WBCs), with other leukocytes or with body cells. The MHC determines donor compatibility for organ transplant, as well as one''s susceptibility to autoimmune diseases. In a cell, protein molecules of the host''s own phenotype or of other biologic entities are continually synthesized and degraded. Each MHC molecule on the cell surface displays a small peptide (a molecular fraction of a protein) called an epitope. The presented self-antigens prevent an organism''s immune system from targeting its own cells. The presentation of pathogen-derived proteins results in the elimination of the infected cell by the immune system.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Major histocompatibility complex', 'Diversity of an individual''s self-antigen presentation, mediated by MHC self-antigens, is attained in at least three ways: (1) an organism''s MHC repertoire is polygenic (via multiple, interacting genes); (2) MHC expression is codominant (from both sets of inherited alleles); (3) MHC gene variants are highly polymorphic (diversely varying from organism to organism within a species). Sexual selection has been observed in male mice choosing to mate with females with different MHCs. Also, at least for MHC I presentation, there has been evidence of antigenic peptide splicing, which can combine peptides from different proteins, vastly increasing antigen diversity.', 'Wikipedia: Major histocompatibility complex', 'https://en.wikipedia.org/w/index.php?title=Major_histocompatibility_complex&oldid=1379602815', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'Diversity of an individual''s self-antigen presentation, mediated by MHC self-antigens, is attained in at least three ways: (1) an organism''s MHC repertoire is polygenic (via multiple, interacting genes); (2) MHC expression is codominant (from both sets of inherited alleles); (3) MHC gene variants are highly polymorphic (diversely varying from organism to organism within a species). Sexual selection has been observed in male mice choosing to mate with females with different MHCs. Also, at least for MHC I presentation, there has been evidence of antigenic peptide splicing, which can combine peptides from different proteins, vastly increasing antigen diversity.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Major histocompatibility complex: Discovery', 'The first descriptions of the MHC were made by British immunologist Peter Gorer in 1936. MHC genes were first identified in inbred mice strains. Clarence Little transplanted tumors across different strains and found rejection of transplanted tumors according to strains of host versus donor. George Snell selectively bred two mouse strains, attained a new strain nearly identical to one of the progenitor strains, but differing crucially in histocompatibility—that is, tissue compatibility upon transplantation—and thereupon identified an MHC locus. Later Jean Dausset demonstrated the existence of MHC genes in humans and described the first human leucocyte antigen, the protein which we call now HLA-A2. Some years later Baruj Benacerraf showed that polymorphic MHC genes not only determine an individual''s unique constitution of antigens but also regulate the interaction among the various cells of the immunological system. These three scientists have been awarded the 1980 Nobel Prize in Physiology or Medicine for their discoveries concerning "genetically determined structures on the cell surface that regulate immunological reactions".', 'Wikipedia: Major histocompatibility complex', 'https://en.wikipedia.org/w/index.php?title=Major_histocompatibility_complex&oldid=1379602815', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The first descriptions of the MHC were made by British immunologist Peter Gorer in 1936. MHC genes were first identified in inbred mice strains. Clarence Little transplanted tumors across different strains and found rejection of transplanted tumors according to strains of host versus donor. George Snell selectively bred two mouse strains, attained a new strain nearly identical to one of the progenitor strains, but differing crucially in histocompatibility—that is, tissue compatibility upon transplantation—and thereupon identified an MHC locus. Later Jean Dausset demonstrated the existence of MHC genes in humans and described the first human leucocyte antigen, the protein which we call now HLA-A2. Some years later Baruj Benacerraf showed that polymorphic MHC genes not only determine an individual''s unique constitution of antigens but also regulate the interaction among the various cells of the immunological system. These three scientists have been awarded the 1980 Nobel Prize in Physiology or Medicine for their discoveries concerning "genetically determined structures on the cell surface that regulate immunological reactions".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Major histocompatibility complex: Discovery', 'The first fully sequenced and annotated MHC was published for humans in 1999 by a consortium of sequencing centers from the UK, USA and Japan in Nature. It was a "virtual MHC" since it was a mosaic from different individuals. A much shorter MHC locus from chickens was published in the same issue of Nature. Many other species have been sequenced and the evolution of the MHC was studied, e.g. in the gray short-tailed opossum (Monodelphis domestica), a marsupial, MHC spans 3.95 Mb, yielding 114 genes, 87 shared with humans. Marsupial MHC genotypic variation lies between eutherian mammals and birds, taken as the minimal MHC encoding, but is closer in organization to that of nonmammals. The IPD-MHC Database was created which provides a centralised repository for sequences of the Major Histocompatibility Complex (MHC) from a number of different species. As of the release on December 19, 2019, the database contains information on 77 species.', 'Wikipedia: Major histocompatibility complex', 'https://en.wikipedia.org/w/index.php?title=Major_histocompatibility_complex&oldid=1379602815', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The first fully sequenced and annotated MHC was published for humans in 1999 by a consortium of sequencing centers from the UK, USA and Japan in Nature. It was a "virtual MHC" since it was a mosaic from different individuals. A much shorter MHC locus from chickens was published in the same issue of Nature. Many other species have been sequenced and the evolution of the MHC was studied, e.g. in the gray short-tailed opossum (Monodelphis domestica), a marsupial, MHC spans 3.95 Mb, yielding 114 genes, 87 shared with humans. Marsupial MHC genotypic variation lies between eutherian mammals and birds, taken as the minimal MHC encoding, but is closer in organization to that of nonmammals. The IPD-MHC Database was created which provides a centralised repository for sequences of the Major Histocompatibility Complex (MHC) from a number of different species. As of the release on December 19, 2019, the database contains information on 77 species.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Major histocompatibility complex: Genes', 'The MHC locus is present in all jawed vertebrates; it is assumed to have arisen about 450 million years ago. Despite the difference in the number of genes included in the MHC of different species, the overall organization of the locus is rather similar. Usual MHC contains about a hundred genes and pseudogenes, not all of which are involved in immunity. In humans, the MHC region occurs on chromosome 6, between the flanking genetic markers MOG and COL11A2 (from 6p22.1 to 6p21.3 about 29Mb to 33Mb on the hg38 assembly), and contains 224 genes spanning 3.6 megabase pairs (3 600 000 bases). About half have known immune functions. The human MHC is also called the HLA (human leukocyte antigen) complex (often just the HLA). Similarly, there is SLA (Swine leukocyte antigens), BoLA (Bovine leukocyte antigens), DLA for dogs, etc. However, historically, the MHC in mice is called the Histocompatibility system 2 or just the H-2, whereas it has been referred to as the RT1 complex in rats, and the B locus in chickens.', 'Wikipedia: Major histocompatibility complex', 'https://en.wikipedia.org/w/index.php?title=Major_histocompatibility_complex&oldid=1379602815', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The MHC locus is present in all jawed vertebrates; it is assumed to have arisen about 450 million years ago. Despite the difference in the number of genes included in the MHC of different species, the overall organization of the locus is rather similar. Usual MHC contains about a hundred genes and pseudogenes, not all of which are involved in immunity. In humans, the MHC region occurs on chromosome 6, between the flanking genetic markers MOG and COL11A2 (from 6p22.1 to 6p21.3 about 29Mb to 33Mb on the hg38 assembly), and contains 224 genes spanning 3.6 megabase pairs (3 600 000 bases). About half have known immune functions. The human MHC is also called the HLA (human leukocyte antigen) complex (often just the HLA). Similarly, there is SLA (Swine leukocyte antigens), BoLA (Bovine leukocyte antigens), DLA for dogs, etc. However, historically, the MHC in mice is called the Histocompatibility system 2 or just the H-2, whereas it has been referred to as the RT1 complex in rats, and the B locus in chickens.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Major histocompatibility complex: Genes', 'The MHC gene family is divided into three subgroups: MHC class I, MHC class II, and MHC class III. Among all those genes present in MHC, there are two types of genes coding for the proteins MHC class I molecules and MHC class II molecules that are directly involved in the antigen presentation. These genes are highly polymorphic, 19031 alleles of class I HLA, and 7183 of class II HLA are deposited for human in the IMGT database.', 'Wikipedia: Major histocompatibility complex', 'https://en.wikipedia.org/w/index.php?title=Major_histocompatibility_complex&oldid=1379602815', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The MHC gene family is divided into three subgroups: MHC class I, MHC class II, and MHC class III. Among all those genes present in MHC, there are two types of genes coding for the proteins MHC class I molecules and MHC class II molecules that are directly involved in the antigen presentation. These genes are highly polymorphic, 19031 alleles of class I HLA, and 7183 of class II HLA are deposited for human in the IMGT database.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Major histocompatibility complex: MHC class I', 'MHC class I molecules are expressed in all nucleated cells and also in platelets—in essence all cells but red blood cells. It presents epitopes to killer T cells, also called cytotoxic T lymphocytes (CTLs). A CTL expresses CD8 receptors, in addition to T-cell receptors (TCRs). When a CTL''s CD8 receptor docks to a MHC class I molecule, if the CTL''s TCR fits the epitope within the MHC class I molecule, the CTL triggers the cell to undergo programmed cell death by apoptosis. Thus, MHC class I helps mediate cellular immunity, a primary means to address intracellular pathogens, such as viruses and some bacteria, including bacterial L forms, bacterial genus Mycoplasma, and bacterial genus Rickettsia. In humans, MHC class I comprises HLA-A, HLA-B, and HLA-C molecules.', 'Wikipedia: Major histocompatibility complex', 'https://en.wikipedia.org/w/index.php?title=Major_histocompatibility_complex&oldid=1379602815', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'MHC class I molecules are expressed in all nucleated cells and also in platelets—in essence all cells but red blood cells. It presents epitopes to killer T cells, also called cytotoxic T lymphocytes (CTLs). A CTL expresses CD8 receptors, in addition to T-cell receptors (TCRs). When a CTL''s CD8 receptor docks to a MHC class I molecule, if the CTL''s TCR fits the epitope within the MHC class I molecule, the CTL triggers the cell to undergo programmed cell death by apoptosis. Thus, MHC class I helps mediate cellular immunity, a primary means to address intracellular pathogens, such as viruses and some bacteria, including bacterial L forms, bacterial genus Mycoplasma, and bacterial genus Rickettsia. In humans, MHC class I comprises HLA-A, HLA-B, and HLA-C molecules.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'immune', 'Major histocompatibility complex: MHC class I', 'The first crystal structure of Class I MHC molecule, human HLA-A2, was published in 1989. The structure revealed that MHC-I molecules are heterodimers. They have a polymorphic heavy α-subunit whose gene occurs inside the MHC locus and small invariant β2 microglobulin subunit whose gene is usually located outside of it. Polymorphic heavy chain of MHC-I molecule contains N-terminal extra-cellular region composed by three domains, α1, α2, and α3, transmembrane helix to hold MHC-I molecule on the cell surface and short cytoplasmic tail. Two domains, α1 and α2, form deep peptide-binding groove between two long α-helices and the floor of the groove formed by eight β-strands. Immunoglobulin-like domain α3 involved in the interaction with CD8 co-receptor. β2 microglobulin provides stability of the complex and participates in the recognition of peptide-MHC class I complex by CD8 co-receptor. The peptide is non-covalently bound to MHC-I, it is held by the several pockets on the floor of the peptide-binding groove. Amino acid side-chains that are most polymorphic in human alleles fill the central and widest portion of the binding groove, while conserved side-chains are clustered at the narrower ends of the groove.', 'Wikipedia: Major histocompatibility complex', 'https://en.wikipedia.org/w/index.php?title=Major_histocompatibility_complex&oldid=1379602815', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'immune' and body = 'The first crystal structure of Class I MHC molecule, human HLA-A2, was published in 1989. The structure revealed that MHC-I molecules are heterodimers. They have a polymorphic heavy α-subunit whose gene occurs inside the MHC locus and small invariant β2 microglobulin subunit whose gene is usually located outside of it. Polymorphic heavy chain of MHC-I molecule contains N-terminal extra-cellular region composed by three domains, α1, α2, and α3, transmembrane helix to hold MHC-I molecule on the cell surface and short cytoplasmic tail. Two domains, α1 and α2, form deep peptide-binding groove between two long α-helices and the floor of the groove formed by eight β-strands. Immunoglobulin-like domain α3 involved in the interaction with CD8 co-receptor. β2 microglobulin provides stability of the complex and participates in the recognition of peptide-MHC class I complex by CD8 co-receptor. The peptide is non-covalently bound to MHC-I, it is held by the several pockets on the floor of the peptide-binding groove. Amino acid side-chains that are most polymorphic in human alleles fill the central and widest portion of the binding groove, while conserved side-chains are clustered at the narrower ends of the groove.');
